  ('fraud.signals.engagement_anomaly.rule', '"Likes under 0.4% of views, or comment ratio an outlier against the account''s 28-day norm."'::jsonb, 'CONTRACT', 'Fraud score 0..100 = min(100, sum(points x severity)). clean <20, watch 20-39, review 40-69 (human review within 24h), high 70+ (auto-hold).'),
