  ('scores.hook_checklist', '[{"id":"hook_lands_2s","label":"Hook lands by 2.0s","weight":20,"rule":"Full if the hook line lands by 2.0 s; half by 3.0 s; otherwise 0."},{"id":"onscreen_text_matches","label":"On-screen text mirrors the spoken hook within 1s","weight":15,"rule":"Full if the spoken hook is also on screen as text within 1.0 s; half if it appears by 2.0 s or only partly matches."},{"id":"face_early","label":"A face is on screen within the first second","weight":15,"rule":"Full if a face is on screen within 1.0 s; half by 2.0 s. Faceless formats get full points."},{"id":"app_visible_3s","label":"App or product visible by 3s","weight":15,"rule":"Full if the app is visible by 3.0 s; half by 5.0 s."},{"id":"pattern_interrupt","label":"Motion or pattern interrupt in the first 1.5s","weight":10,"rule":"Full if there is a cut, motion or visual pattern interrupt in the first 1.5 s."},{"id":"proven_hook_type","label":"Uses a proven hook type","weight":10,"rule":"Full if the hook is a library hook type with an above-median trial rate; half for any other library hook type; 0 otherwise."},{"id":"speech_starts_fast","label":"Speech starts within 1s, no dead air","weight":10,"rule":"Full if speech starts within 1.0 s; half within 2.0 s."},{"id":"captions_safe_zone","label":"Captions burned in, inside safe zones","weight":5,"rule":"Full if captions are burned in and inside the platform safe zones; otherwise 0."}]'::jsonb, 'CONTRACT', 'Checklist scores (not learned). Hook Score checklist weights sum to 100; Flow Score checklist weights sum to 100. Bands A 85+, B 70-84, C 55-69, D 40-54, E below 40.'),
  ('scores.flow_checklist', '[{"id":"hook_score","label":"Hook Score (scaled)","weight":30,"rule":"round(Hook Score points x 0.30)."},{"id":"required_beats","label":"Required beats covered","weight":25,"rule":"round(25 x required beats found / required beats in the brief)."},{"id":"app_visible_early","label":"App on screen early","weight":10,"rule":"Full if the app is on screen by 3.0 s; half by 8.0 s."},{"id":"disclosure","label":"Disclosure present (audio and on-screen)","weight":10,"rule":"10 if #ad is both spoken and on screen; 5 if only one; 0 if neither (a missing disclosure also blocks settlement)."},{"id":"length_ok","label":"Length 15 to 30 seconds","weight":5,"rule":"Full for 15 to 30 s; half for 10 to 15 s or 30 to 45 s; otherwise 0."},{"id":"captions_safe_zone","label":"Captions inside safe zones","weight":5,"rule":"Full if captions are inside the platform safe zones; otherwise 0."},{"id":"single_cta_win_state","label":"One CTA, ends on a win state","weight":5,"rule":"Full if there is exactly one CTA and the video ends on a win state; half if one of the two."},{"id":"audio_clear","label":"Audio clear, no dead air","weight":5,"rule":"Full if speech is clear with no dead air over 1.0 s; half if there is one gap."},{"id":"format_fit","label":"Follows the chosen format''s beats","weight":5,"rule":"Full if the video follows the format''s beat order; half if one beat is out of order."}]'::jsonb, 'CONTRACT', 'Checklist scores (not learned). Hook Score checklist weights sum to 100; Flow Score checklist weights sum to 100. Bands A 85+, B 70-84, C 55-69, D 40-54, E below 40.'),
